def chain_chain(chain):
    chain_dict = {}
    for token in chain:
        if token not in chain_dict:
            chain_dict[token] = []
        chain_dict[token].append(token)

    chain_dict = {k: v for k, v in chain_dict.items() if v}

    def dfs(current, path):
        if current in chain_dict:
            chain_dict[current].append(path)
            return chain_dict[current]
        else:
            return []

    result = dfs(chain[0], [chain[0]])
    return ','.join(result)
